import * as T from './vendor/three.module.js';
import {arity,evaluateCircuit,connectCircuit} from './circuit.mjs';
export function createFreeLab(api){
 const {$,scene,person,people,mesh,mat,projectLabel,announce}=api;
 let enabled=false,nodes=[],edges=[],serial=0,selected=null,wireStart=null,wiring=false,values=new Map(),wireVisuals=[];
 const inspector=$('.inspector'), basicNote=document.createElement('div');while(inspector.firstChild)basicNote.append(inspector.firstChild);inspector.append(basicNote);
 const note=document.createElement('div');note.className='free-note';note.hidden=true;note.innerHTML=`<div class="section-title">자유 배선 <span>FREE LAB</span></div><p>출력을 고른 뒤 다른 사람의 입력 A·B를 연결하세요. 한 출력을 여러 곳으로 나눌 수도 있어요.</p><label>보내는 사람<select id="wire-from"></select></label><label>받는 사람<select id="wire-to"></select></label><label>입력 단자<select id="wire-port"><option value="0">입력 A</option><option value="1">입력 B</option></select></label><button id="connect-wire" class="free-primary">선 연결하기</button><p id="wire-message" role="status"></p><div class="section-title">연결한 선 <span id="edge-count">0개</span></div><div id="edge-list"></div><button id="free-feed">🍪 모두에게 간식 주기</button><button id="free-restore">↺ 사람들을 제자리에</button><div class="free-examples"><button id="free-example">4명 입력 예제</button><button id="free-clear">빈 실험장</button></div><p class="free-small">AND·OR·XOR는 입력 2개, NOT은 1개를 받아요. 3명 이상은 게이트를 이어 연결하세요. ‘—’는 입력 미연결 또는 자리 이탈이에요.</p>`;inspector.append(note);
 const switchButton=document.createElement('button');switchButton.id='free-mode';switchButton.className='free-primary';switchButton.textContent='＋ 자유 실험실';$('#presets').after(switchButton);
 const summary=document.createElement('div');summary.className='free-summary';summary.hidden=true;summary.innerHTML='<div class="eyebrow">SELECTED COMPONENT</div><strong id="selected-name">부품을 선택하세요</strong><div class="free-actions"><select id="node-select" aria-label="배치한 부품 선택"></select><button id="toggle-value">0 ↔ 1</button><button id="remove-node">삭제</button></div><p id="selected-state"></p>';$('.bottom-panel').prepend(summary);
 const wireButton=document.createElement('button');wireButton.id='wire-mode';wireButton.textContent='⌁ 배선';wireButton.hidden=true;$('#move').after(wireButton);
 const freeParts=document.createElement('div');freeParts.className='parts free-parts';freeParts.hidden=true;freeParts.innerHTML=['1','0','AND','OR','XOR','NOT','LAMP'].map(k=>`<button class="part" data-add="${k}">${k==='LAMP'?'💡 전구':k+' 사람'} ＋</button>`).join('');$('#parts').after(freeParts);
 const inputExtras=document.createElement('div');inputExtras.className='parts input-extras';inputExtras.innerHTML='<button class="part" data-extra="1">1 사람 ＋</button><button class="part" data-extra="0">0 사람 ＋</button>';$('#parts').before(inputExtras);
 const title=n=>`${n.kind==='INPUT'?n.value:n.kind==='LAMP'?'전구':n.kind} · #${n.id}`;
 const get=n=>nodes.find(x=>x.id===n);
 function sync(){const opts=ns=>ns.map(n=>`<option value="${n.id}">${title(n)}</option>`).join('');for(const [id,list] of [['#wire-from',nodes.filter(n=>n.kind!=='LAMP')],['#wire-to',nodes.filter(n=>arity(n.kind))],['#node-select',nodes]]){const el=$(id),prev=el.value;el.innerHTML=opts(list);if(list.some(n=>n.id===prev))el.value=prev;}if(selected)$('#node-select').value=selected.id;syncPort();$('#edge-count').textContent=edges.length+'개';$('#edge-list').innerHTML=edges.map((e,i)=>`<div class="edge-row"><span>${title(get(e.from))} → ${title(get(e.to))} ${e.port?'B':'A'}</span><button data-edge="${i}" aria-label="이 연결 삭제">×</button></div>`).join('');$('#edge-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{edges.splice(+b.dataset.edge,1);redraw();sync();update()});update();}
 function syncPort(){const n=get($('#wire-to').value);$('#wire-port').options[1].disabled=!n||arity(n.kind)<2;if(!n||arity(n.kind)<2)$('#wire-port').value='0';}
 function link(from,to,port){try{edges=connectCircuit(nodes,edges,from,to,port);wireStart=null;$('#wire-message').textContent='연결했어요. 이미 연결된 입력은 새 선으로 바뀝니다.';redraw();sync();announce('선이 연결됐어요.');}catch(e){$('#wire-message').textContent=e.message;announce(e.message)}}
 function makeLamp(pos){const group=new T.Group(),body=new T.Group();scene.add(group);group.add(body);group.position.copy(pos);mesh(new T.CylinderGeometry(.55,.65,.2,24),mat(0x899b70),body,0,.12,0);mesh(new T.CylinderGeometry(.2,.25,.3,16),mat(0xa8b29b),body,0,.4,0);const bulb=mat(0xe5e8ce,{emissive:0xdfff55,emissiveIntensity:0,roughness:.25});mesh(new T.SphereGeometry(.5,24,16),bulb,body,0,.95,0);const label=document.createElement('div');label.className='person-label';$('#labels').append(label);const p={role:'LAMP',group,body,label,legs:[],hairs:[],cookie:new T.Object3D(),age:0,fed:true,on:false,home:pos.clone(),seed:0,bulb,isLamp:true};group.traverse(o=>o.userData.person=p);people.push(p);return p;}
 function nextPosition(){for(let z=-2.6;z<=2.6;z+=1.3)for(let x=-5.2;x<=5.2;x+=1.3)if(nodes.every(n=>Math.hypot(n.p.home.x-x,n.p.home.z-z)>1.1))return new T.Vector3(x,.21,z);return new T.Vector3(0,.21,3.3);}
 function add(kind,pos,value){if(nodes.length>=28){announce('이번 실험장은 최대 28개 부품까지 놓을 수 있어요.');return null;}if(kind==='0'||kind==='1'){value=+kind;kind='INPUT';}const p=kind==='LAMP'?makeLamp(pos||nextPosition()):person(kind==='INPUT'?(value?'ONE':'ZERO'):kind,pos||nextPosition());p.free=true;p.fed=kind==='LAMP';const n={id:String(++serial),kind,value:value??0,p};nodes.push(n);p.node=n;
 const anchor=mesh(new T.TorusGeometry(.53,.022,6,32),mat(0xacb995),scene,p.home.x,.235,p.home.z);anchor.rotation.x=-Math.PI/2;n.anchor=anchor;
 const ports=document.createElement('div');ports.className='node-ports';ports.innerHTML=`<button data-select="1">${title(n)}</button>${kind!=='LAMP'?'<button data-out="1" title="이 출력에서 연결">출력</button>':''}${Array.from({length:arity(kind)},(_,i)=>`<button data-in="${i}">입력 ${i?'B':'A'}</button>`).join('')}`;$('#labels').append(ports);n.ports=ports;ports.querySelector('[data-select]').onclick=()=>select(p);const out=ports.querySelector('[data-out]');if(out)out.onclick=()=>{wireStart=n.id;wiring=true;wireButton.classList.add('active');announce(title(n)+' 출력 선택. 연결할 입력 A·B를 누르세요.');};ports.querySelectorAll('[data-in]').forEach(b=>b.onclick=()=>{if(wireStart)link(wireStart,n.id,+b.dataset.in);else announce('먼저 보내는 사람의 출력 단자를 누르세요.');});select(p);sync();return n;}
 function select(p){if(!p?.node)return;selected=p.node;api.setSelected(p);$('#node-select').value=selected.id;update();}
 function destroy(n){n.ports.remove();scene.remove(n.anchor);n.anchor.geometry.dispose();n.anchor.material.dispose();api.removePerson(n.p);}
 function clear(){nodes.forEach(destroy);nodes=[];edges=[];selected=null;api.setSelected(null);wireStart=null;$('#wire-message').textContent='';redraw();sync();}
 function example(){clear();serial=0;const specs=[['1',-5,-2.5],['1',-5,-.8],['0',-5,1],['0',-5,2.8],['AND',-2,-1.7],['XOR',-2,1.8],['OR',1,0],['LAMP',4,0]];specs.forEach(([k,x,z])=>add(k,new T.Vector3(x,.21,z)));const ids=nodes.map(n=>n.id);edges=[[0,4,0],[1,4,1],[2,5,0],[3,5,1],[4,6,0],[5,6,1],[6,7,0]].map(([f,t,port])=>({from:ids[f],to:ids[t],port}));redraw();sync();}
 function redraw(){wireVisuals.forEach(w=>{scene.remove(w.mesh);w.mesh.geometry.dispose();w.mesh.material.dispose();scene.remove(w.dot);w.dot.geometry.dispose();w.dot.material.dispose()});wireVisuals=edges.map(e=>{const a=get(e.from).p.home.clone(),b=get(e.to).p.home.clone();a.x+=.45;b.x-=.45;b.z+=(e.port?1:-1)*.2;a.y=b.y=.32;const m=a.clone().lerp(b,.5);m.y=.42;const curve=new T.QuadraticBezierCurve3(a,m,b);const material=mat(0xaabb91,{emissive:0xb5e639,emissiveIntensity:0});return {edge:e,curve,mesh:mesh(new T.TubeGeometry(curve,24,.038,6,false),material,scene),dot:mesh(new T.SphereGeometry(.07,8,8),mat(0xe8ff50,{emissive:0xe8ff50,emissiveIntensity:1}),scene)};});}
 function update(){if(!enabled)return;const unavailable=new Set(nodes.filter(n=>n.p.group.position.distanceTo(n.p.home)>.72).map(n=>n.id));values=evaluateCircuit(nodes,edges,unavailable);nodes.forEach(n=>{n.p.on=values.get(n.id)===1;if(n.p.bulb)n.p.bulb.emissiveIntensity=n.p.on?1.8:0;});wireVisuals.forEach(w=>{const valid=!unavailable.has(w.edge.from)&&!unavailable.has(w.edge.to),v=valid?values.get(w.edge.from):null;w.mesh.material.color.set(v===1?0xaacb39:v===0?0xa7b797:0xd69b83);w.mesh.material.emissiveIntensity=v===1?.5:0;w.dot.visible=v===1;});
 const lamps=nodes.filter(n=>n.kind==='LAMP');$('#output').textContent=lamps.length===1?(values.get(lamps[0].id)??'—'):lamps.length+'개';$('#output-text').textContent=lamps.length===1?(values.get(lamps[0].id)===null?'미연결 / 자리 이탈':values.get(lamps[0].id)?'전구 켜짐':'전구 꺼짐'):lamps.length?'각 전구 위에서 확인':'전구를 추가하세요';$('.result').classList.toggle('on',lamps.some(n=>values.get(n.id)===1));$('#selected-name').textContent=selected?title(selected):'부품을 선택하세요';$('#selected-state').textContent=selected?`출력 ${values.get(selected.id)??'—'} · ${selected.p.isLamp?'전구':selected.p.fed?'🍪 자리 고정':selected.p.age>=22?'자리를 떠나는 중':Math.ceil(22-selected.p.age)+'초 동안 얌전'}`:'왼쪽에서 1·0 사람과 게이트를 추가하세요.';$('#toggle-value').disabled=selected?.kind!=='INPUT';$('#remove-node').disabled=!selected;
 }
 function tick(t){if(!enabled)return;nodes.forEach(n=>{n.p.label.textContent=`${title(n)} → ${values.get(n.id)??'—'}${n.p.fed&&!n.p.isLamp?' 🍪':''}`;n.p.label.classList.toggle('energized',values.get(n.id)===1);n.ports.hidden=!wiring;n.ports.querySelector('[data-select]').textContent=title(n);projectLabel(n.ports,n.p.group.position.clone().add(new T.Vector3(0,3.2,0)));});wireVisuals.forEach(w=>w.dot.position.copy(w.curve.getPoint((t*.35)%1)));}
 function place(p,v){if(!p?.node||!nodes.includes(p.node)||!v)return;p.group.position.set(T.MathUtils.clamp(v.x,-6,6),.21,T.MathUtils.clamp(v.z,-3.3,3.3));p.home.copy(p.group.position);p.age=0;p.node.anchor.position.set(p.home.x,.235,p.home.z);select(p);redraw();update();}
 function reset(){nodes.forEach(n=>{n.p.group.position.copy(n.p.home);n.p.age=0});update();}
 function feedAll(){nodes.forEach(n=>{n.p.fed=true;n.p.cookie.visible=!n.p.isLamp;});update();announce('간식을 줬어요. 이제 자리를 지켜요.');}
 function toggle(on){enabled=on;api.setSelected(null);document.body.classList.toggle('free-lab',on);basicNote.hidden=on;note.hidden=!on;summary.hidden=!on;wireButton.hidden=!on;freeParts.hidden=!on;inputExtras.hidden=on;$('#parts').hidden=on;$('.input-zone').hidden=on;$('.formula-zone').hidden=on;switchButton.classList.toggle('active',on);switchButton.textContent=on?'✓ 자유 실험실':'＋ 자유 실험실';api.setMode('move');wiring=false;wireStart=null;wireButton.classList.remove('active');[...api.getActive(),...people.filter(p=>p.pool)].forEach((p,i)=>{const visible=!on&&(p.role!=='B'||api.getType()!=='NOT');p.group.visible=visible;p.label.hidden=!visible;});api.lamp.visible=!on;api.lampLabel.hidden=on;api.rings.forEach((r,i)=>r.visible=!on&&(i!==1||api.getType()!=='NOT'));api.wires.forEach((w,i)=>{w.m.visible=!on&&(i!==1||api.getType()!=='NOT');w.pulses.forEach(p=>p.visible=!on)});nodes.forEach(n=>{n.p.group.visible=on;n.p.label.hidden=!on;n.anchor.visible=on;n.ports.hidden=true});wireVisuals.forEach(w=>{w.mesh.visible=on;w.dot.visible=on});if(on){$('#experiment').textContent='자유 실험실';$('#instruction').textContent='사람 추가 → 배치 → 출력과 입력을 연결하세요.';if(!nodes.length)example();sync();}else api.update();api.refreshView();}
 for(const id of ['#move','#feed'])$(id).addEventListener('click',()=>{wiring=false;wireStart=null;wireButton.classList.remove('active')});
 switchButton.onclick=()=>toggle(true);freeParts.querySelectorAll('button').forEach(b=>b.onclick=()=>add(b.dataset.add));inputExtras.querySelectorAll('button').forEach(b=>b.onclick=()=>{toggle(true);add(b.dataset.extra)});wireButton.onclick=()=>{wiring=!wiring;wireStart=null;api.setMode('move');wireButton.classList.toggle('active',wiring);announce(wiring?'보내는 사람의 출력 → 받는 사람의 입력을 누르세요.':'배치 모드로 돌아왔어요.')};$('#wire-to').onchange=syncPort;$('#connect-wire').onclick=()=>link($('#wire-from').value,$('#wire-to').value,+$('#wire-port').value);$('#node-select').onchange=()=>select(get($('#node-select').value)?.p);$('#toggle-value').onclick=()=>{if(selected?.kind==='INPUT'){selected.value=1-selected.value;selected.p.role=selected.value?'ONE':'ZERO';sync()}};$('#remove-node').onclick=()=>{if(!selected)return;const id=selected.id;destroy(selected);nodes=nodes.filter(n=>n.id!==id);edges=edges.filter(e=>e.from!==id&&e.to!==id);selected=nodes[0]??null;api.setSelected(selected?.p??null);wireStart=null;redraw();sync();};$('#free-feed').onclick=feedAll;$('#free-restore').onclick=reset;$('#free-clear').onclick=clear;$('#free-example').onclick=example;
 return {get enabled(){return enabled},toggle,place,select,update,tick,reset,feedAll,getNodes:()=>nodes,snapshot:()=>({nodes:nodes.map(n=>({id:n.id,kind:n.kind,value:n.value,output:values.get(n.id)})),edges:edges.map(e=>({...e}))})};
}
